using System;
using System.Threading.Tasks;
using Grpc.Core;

namespace Ondewo.Nlu.Client.Auth
{
    /// <summary>
    /// Bearer-token authentication for the generated ONDEWO NLU gRPC clients.
    /// <para>
    /// This is the only hand-written source in this package; everything under <c>api/</c> is
    /// generated by the ondewo-proto-compiler image. It is picked up by the SDK's default
    /// <c>Compile</c> glob and therefore ships inside the NuGet package beside the stubs.
    /// </para>
    /// <para>
    /// An ONDEWO server authenticates a call through an <c>authorization: Bearer &lt;token&gt;</c>
    /// metadata entry. Attach it per call with <see cref="CreateBearerMetadata"/>, or once for the
    /// lifetime of a channel with <see cref="CreateBearerCredentials"/>:
    /// </para>
    /// <code>
    /// var channel = GrpcChannel.ForAddress("https://nlu.ondewo.com:443");
    /// var client = new Users.UsersClient(channel);
    /// var user = client.GetUser(request, OndewoAuth.CreateBearerMetadata(token));
    /// </code>
    /// </summary>
    public static class OndewoAuth
    {
        /// <summary>
        /// Name of the gRPC metadata entry carrying the token. gRPC rejects a non-lowercase
        /// metadata key at runtime, so this is deliberately spelled in lower case.
        /// </summary>
        public const string AuthorizationHeader = "authorization";

        /// <summary>Scheme prefix of the authorization header value, including its separator.</summary>
        public const string BearerPrefix = "Bearer ";

        /// <summary>
        /// Builds call metadata carrying <paramref name="accessToken"/>, for the optional
        /// <c>headers</c> argument every generated client method accepts.
        /// </summary>
        /// <param name="accessToken">The ONDEWO access token.</param>
        /// <returns>Metadata holding exactly the authorization entry.</returns>
        /// <exception cref="ArgumentException">The token is null, empty or whitespace.</exception>
        public static Metadata CreateBearerMetadata(string accessToken)
        {
            return new Metadata { { AuthorizationHeader, FormatBearer(accessToken) } };
        }

        /// <summary>
        /// Builds the interceptor that adds <paramref name="accessToken"/> to the metadata of
        /// every call it is applied to.
        /// </summary>
        /// <param name="accessToken">The ONDEWO access token.</param>
        /// <returns>An interceptor that appends the authorization entry.</returns>
        /// <exception cref="ArgumentException">The token is null, empty or whitespace.</exception>
        public static AsyncAuthInterceptor CreateBearerInterceptor(string accessToken)
        {
            // Validated here rather than inside the interceptor: a bad token then fails where it
            // was configured instead of on the first call, with no useful stack to point at it.
            string headerValue = FormatBearer(accessToken);
            return (context, metadata) =>
            {
                metadata.Add(AuthorizationHeader, headerValue);
                return Task.CompletedTask;
            };
        }

        /// <summary>
        /// Builds call credentials carrying <paramref name="accessToken"/>, to be combined with
        /// channel credentials so every call on the channel is authenticated.
        /// </summary>
        /// <param name="accessToken">The ONDEWO access token.</param>
        /// <returns>Call credentials that append the authorization entry.</returns>
        /// <exception cref="ArgumentException">The token is null, empty or whitespace.</exception>
        public static CallCredentials CreateBearerCredentials(string accessToken)
        {
            return CallCredentials.FromInterceptor(CreateBearerInterceptor(accessToken));
        }

        private static string FormatBearer(string accessToken)
        {
            if (string.IsNullOrWhiteSpace(accessToken))
            {
                throw new ArgumentException(
                    "an ONDEWO access token is required - it is empty or whitespace",
                    nameof(accessToken));
            }

            return BearerPrefix + accessToken;
        }
    }
}
